d.selection.select([[0, 880], [1920, 880], [1920, 1080], [0, 1080]], SelectionType.REPLACE, 0, false);
executeAction(S2T('cutToLayer'), undefined, DialogModes.NO);
d.activeLayer.visible = false; d.layers.getByName('Layer 0 copy').visible = false;

for _ in range(15):
    s.Bitmap.ApplyBitmapEffect("PGD plan", "GaussianBlurEffect Radius=250")
result = s

var c = new ActionDescriptor(); c.putDouble(C2T('Rd  '), 31); c.putDouble(C2T('Grn '), 111); c.putDouble(C2T('Bl  '), 235);
var t = new ActionDescriptor(); t.putObject(C2T('Clr '), C2T('RGBC'), c);
var u = new ActionDescriptor(); u.putObject(C2T('Type'), S2T('solidColorLayer'), t);
var r = new ActionReference(); r.putClass(S2T('contentLayer'));
var m = new ActionDescriptor(); m.putReference(C2T('null'), r); m.putObject(C2T('Usng'), S2T('contentLayer'), u);
executeAction(tk('make'), m, DialogModes.NO);
